(* [comment removed for export] *)
Theorem art_free3P_pre :
  forall (Q : list aev -> machine_state -> Prop) (log : list aev) regs (M0 rom : word -> option byte) (raw0 : word)
         (S HI p q16 n nl nh qr b1 tp key tsd ctx t spb ris qs l2 blk top bot : Z) (kb : nat) (ia : bool),
    let c := t + 80 in
    let ca := t + 208 in
    getr regs 1 = raw0 -> ret_ok raw0 -> getr regs 2 = Z_to_bv 64 S -> getr regs 4 = Z_to_bv 64 tp -> getr regs 10 = Z_to_bv 64 p ->
    (* [comment removed for export] *)
    0x6c0000 + 16 <= p -> p = 16 * q16 -> 2 ^ 28 < n < 2 ^ 39 -> 0 <= nl < 2 ^ 32 -> 0 <= nh < 2 ^ 7 -> n = nl + 2 ^ 32 * nh -> n <= 8 * qr <= n + 7 -> 0 <= b1 < 256 -> b1 mod 4 = 1 ->
    (art_poison_lo_ok p (8 * qr) \/ art_poison_hi_ok p (8 * qr)) ->
    (p < spb \/ spb + 2 ^ 37 <= p - 16) ->
    (* [comment removed for export] *)
    art_geo HI t ctx tp tsd spb ris qs -> HI + 4096 <= S - 4096 -> S < 2 ^ 47 -> S mod 16 = 0 ->
    0 <= bot -> bot < top -> 4096 <= top -> top < 2 ^ 63 -> 0x68bde8 <= tp - 88 -> 0x68bde8 <= tsd ->
    l2 + 2 ^ 20 <= HI -> blk + 2 ^ 23 <= HI ->
    apart l2 (2 ^ 20) t 4096 -> apart l2 (2 ^ 20) ctx 4096 -> apart l2 (2 ^ 20) spb (2 ^ 37 + 4096) -> apart l2 (2 ^ 20) 0x7fff7000 (0x10007fff8000 - 0x7fff7000) ->
    apart blk (2 ^ 23) t 4096 -> apart blk (2 ^ 23) ctx 4096 -> apart blk (2 ^ 23) spb (2 ^ 37 + 4096) -> apart blk (2 ^ 23) 0x7fff7000 (0x10007fff8000 - 0x7fff7000) ->
    (* [comment removed for export] *)
    p + 8 <= HI -> apart (p - 16) 24 t 4096 -> apart (p - 16) 24 ctx 4096 -> apart (p - 16) 24 l2 (2 ^ 20) -> apart (p - 16) 24 blk (2 ^ 23) ->
    apart (p - 16) 24 ris 4096 -> apart (p - 16) 24 (spb + 24 * 2 ^ 32 + 3758096384) (2 ^ 29) ->
    (* [comment removed for export] *)
    wrA M0 (S - 4096) 4096 -> readable8 M0 S top -> wrA M0 t 4096 -> wrA M0 (p - 16) 24 -> wrA M0 (2147450880 + 2 * q16) qr ->
    wrA M0 0x1f9988 4 -> wrA M0 0x16b100 0x81030 ->
    art_layout M0 -> art_tsd M0 tp key tsd ctx t -> art_prim_consts spb ris M0 ->
    cellA M0 0x16abd8 1 1 -> cellA M0 0x16abfc 4 30 -> cellA M0 (0x1fba28 + 34) 1 1 -> cellA M0 (t + 3168) 1 0 -> cellA M0 (t + 40) 1 0 ->
    cellA M0 (t + 8) 8 top -> cellA M0 (t + 16) 8 bot ->
    cellA M0 0x1f9988 4 (if ia then 1 else 0) -> (ia = true -> forall k, 0 <= k < 2 ^ 15 -> cellA M0 (0x16b108 + 8 * k) 8 0) ->
    cellA M0 (p - 16) 4 (2 + 256 * b1 + 65536 * nh) -> cellA M0 (p - 12) 4 nl ->
    cellA M0 0x1fb9c8 8 0 -> cellA M0 t 8 ctx -> cellA M0 (ctx + 8) 4 0 ->
    cellA M0 (0x166b70 + 80) 8 (2 ^ 20) -> cellA M0 (0x166b70 + 64) 8 (2 ^ 28) -> cellA M0 (0x1676f8 + 48) 4 0 -> cellA M0 (1468568 + 32) 8 spb ->
    (* [comment removed for export] *)
    DInvD l2 blk (Datatypes.S kb) M0 -> DRoD M0 ->
    (* [comment removed for export] *)
    (forall r7 (M7 : word -> option byte) (id : Z),
        getr r7 1 = (0x5ecac : bv 64)%bv -> getr r7 2 = Z_to_bv 64 (S - 2208) -> getr r7 4 = Z_to_bv 64 tp -> getr r7 8 = Z_to_bv 64 0x166b70 -> getr r7 9 = Z_to_bv 64 (t + 80) ->
        getr r7 10 = Z_to_bv 64 (S - 2208) -> getr r7 11 = Z_to_bv 64 (p - 16) -> getr r7 12 = Z_to_bv 64 (t + 208) -> getr r7 13 = Z_to_bv 64 (S - 2128) -> getr r7 14 = Z_to_bv 64 (p - 16) ->
        getr r7 15 = Z_to_bv 64 n -> getr r7 18 = Z_to_bv 64 (U (0x81f08 : bv 64)%bv) -> getr r7 19 = Z_to_bv 64 1 -> getr r7 20 = Z_to_bv 64 (S - 2128) -> getr r7 22 = Z_to_bv 64 (2 ^ 20) ->
        (forall r : reg, In r [3; 23; 24; 25; 26; 27]%bv -> getr r7 r = getr regs r) ->
        0 <= id < 2 ^ 32 ->
        mem_grows M0 M7 -> art_agree (art_free3P_W S t p l2 blk) M0 M7 ->
        cellA M7 (t + 3168) 1 0 -> cellA M7 (p - 16) 4 (3 + 256 * b1 + 65536 * nh) -> cellA M7 (p - 12) 4 nl -> cellA M7 p 8 id ->
        DInvD l2 blk kb M7 -> cellA M7 0x1f9988 4 1 -> (forall k, 0 <= k < 2 ^ 15 -> cellA M7 (0x16b108 + 8 * k) 8 0) ->
        cellA M7 (S - 2136) 8 0x81f78 -> cellA M7 (S - 2144) 8 S -> cellA M7 (S - 2152) 8 p -> cellA M7 (S - 2160) 8 0x81f08 -> cellA M7 (S - 2168) 8 1 ->
        cellA M7 (S - 2176) 8 (S - 2128) -> cellA M7 (S - 2184) 8 (S - 81) -> cellA M7 (S - 2192) 8 (U (getr regs 22)) -> cellA M7 (S - 2200) 8 (S - 2128) -> cellA M7 (S - 2208) 8 (t + 208) ->
        cellA M7 (S - 8) 8 (U raw0) -> cellA M7 (S - 16) 8 (U (getr regs 8)) -> cellA M7 (S - 24) 8 (U (getr regs 9)) -> cellA M7 (S - 32) 8 (U (getr regs 18)) ->
        cellA M7 (S - 40) 8 (U (getr regs 19)) -> cellA M7 (S - 48) 8 (U (getr regs 20)) -> cellA M7 (S - 56) 8 (U (getr regs 21)) ->
